<?php

namespace App\Services\Finance;

use App\Services\QrCodes;
use Illuminate\Support\Facades\Storage;

/**
 * The QR codes a payer sees: one generated by the system from the payment link (always first), plus up to two
 * the committee uploaded themselves (e.g. a DuitNow QR).
 *
 * @phpstan-type Qr array{kind: 'generated'|'uploaded', label: string, svg?: string, url?: string, path?: string}
 */
class PaymentQrCodes
{
    public function __construct(private readonly QrCodes $qr) {}

    /**
     * @param  list<string>|null  $uploaded
     * @return list<array<string, string>>
     */
    public function for(?string $paymentUrl, ?array $uploaded): array
    {
        $codes = $paymentUrl ? [['kind' => 'generated', 'label' => 'Scan to open the payment link', 'svg' => $this->qr->svg($paymentUrl)]] : [];
        foreach ($uploaded ?? [] as $i => $path) {
            $codes[] = ['kind' => 'uploaded', 'label' => 'Payment QR '.($i + 1), 'url' => Storage::disk('public')->url($path), 'path' => $path];
        }

        return $codes;
    }
}
